export const ARTIST_RECOVERY_REWIND_CODEC_MAX_BYTES = 524288;
function exact(value: unknown, keys: readonly string[], label: string): void { if (!value || typeof value !== "object" || Array.isArray(value)) throw Error(`${label} must be an object`); const actual = Reflect.ownKeys(value); if (actual.length !== keys.length || actual.some(k => typeof k !== "string" || !keys.includes(k))) throw Error(`${label} has missing or unknown fields`); }
